                   const vector<Row>* table_rows,
                   const Vector& query_vector,
                   int limit);
    void Open() override;               // YOU IMPLEMENT
    optional<Row> Next() override;       // YOU IMPLEMENT
    void Close() override {}             // provided (no-op)
private:
    DiskANNIndex* index_;
    const vector<Row>* table_rows_;     // rows indexed by node_id
    Vector query_vector_;
    int limit_;
    vector<uint32_t> result_ids_;       // node_ids from Search
    size_t idx_;
};
```

The Engine (already wired) creates a `VectorScanExec` when it encounters a `PhysicalVectorScan` plan node. It passes the DiskANN index, the table's rows, the query vector, and the LIMIT value.
